def cache_sim(capacity, ttl, ops):
    from collections import OrderedDict

    cache = OrderedDict()
    write_time = {}
    results = []

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op

            # Check if key already exists and is not expired
            if key in cache and write_time[key] + ttl > t:
                # Move to end (most recently used)
                cache.move_to_end(key)
            else:
                # If key doesn't exist or is expired
                if key not in cache or write_time[key] + ttl <= t:
                    # If cache is full and key is new, evict LRU
                    if len(cache) >= capacity and key not in cache:
                        lru_key = next(iter(cache))
                        del cache[lru_key]
                        del write_time[lru_key]
                    elif key in cache:
                        # Key exists but is expired, remove it first
                        del cache[key]
                        del write_time[key]

                # Add the new entry
                cache[key] = value
                write_time[key] = t

        elif op[0] == 'get':
            _, t, key = op

            # Check if key exists and is not expired
            if key in cache and write_time[key] + ttl > t:
                results.append(cache[key])
                # Move to end (most recently used)
                cache.move_to_end(key)
            else:
                results.append(-1)

    return results

